import java.time.*;
import java.time.temporal.ChronoUnit;
import java.util.*;

record DateRange(LocalDate from, LocalDate to) {
    String validate() {
        if (from.isAfter(to)) return "期間が逆です";
        long days = ChronoUnit.DAYS.between(from, to) + 1;
        if (days > 31) return "期間は31日以内です";
        return "valid days=" + days;
    }
}

public class ValidateRange {
    public static void main(String[] a) {
        Scanner sc = new Scanner(System.in);
        System.out.println(new DateRange(LocalDate.parse(sc.next()), LocalDate.parse(sc.next())).validate());
    }
}

