import java.util.*;

record CreateOrder(String item, int count) { }

record ApiResult(int status, String body) { }

class OrderService {
    private final Map<String, Integer> stock = new HashMap<>(Map.of("book", 3, "pen", 1));

    ApiResult create(CreateOrder in) {
        if (in.item().isBlank() || in.count() < 1) return new ApiResult(400, "VALIDATION_ERROR");
        Integer current = stock.get(in.item());
        if (current == null) return new ApiResult(404, "NOT_FOUND");
        if (current < in.count()) return new ApiResult(409, "OUT_OF_STOCK");
        int rest = current - in.count();
        stock.put(in.item(), rest);
        return new ApiResult(201, in.item() + " " + in.count() + " rest=" + rest);
    }
}

public class Main {
    public static void main(String[] args) {
        Scanner sc = new Scanner(System.in);
        String item = sc.next();
        if (item.equals("_")) item = "";
        ApiResult r = new OrderService().create(new CreateOrder(item, sc.nextInt()));
        System.out.println(r.status() + " " + r.body());
    }
}
